import { randomUUID } from 'node:crypto'
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises'
import path from 'node:path'

// Books live in a plain JSON file so they survive a restart without a database.
// Override the location with BOOKS_DATA_DIR (used by the tests).
function dataFile() {
  const dir = process.env.BOOKS_DATA_DIR || path.join(process.cwd(), 'data')
  return path.join(dir, 'books.json')
}

export const READING = 'reading'
export const FINISHED = 'finished'

// Next runs server actions concurrently, so every read-modify-write goes through
// this promise chain. Without it two submissions racing on the same file would
// each write a copy of the list that is missing the other's book.
let tail = Promise.resolve()

function withLock(fn) {
  const run = tail.then(fn)
  tail = run.then(
    () => {},
    () => {},
  )
  return run
}

async function readAll() {
  try {
    const raw = await readFile(dataFile(), 'utf8')
    const parsed = JSON.parse(raw)
    return Array.isArray(parsed) ? parsed : []
  } catch (err) {
    if (err.code === 'ENOENT') return []
    throw err
  }
}

async function writeAll(books) {
  const file = dataFile()
  await mkdir(path.dirname(file), { recursive: true })
  // Write-then-rename so a crash mid-write can't leave a truncated file behind.
  const tmp = `${file}.${randomUUID()}.tmp`
  await writeFile(tmp, `${JSON.stringify(books, null, 2)}\n`, 'utf8')
  await rename(tmp, file)
}

function slugify(text) {
  return text
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60)
}

// Readable ids keep shared links legible: /books/dune-3f9a2c
function makeId(title, existing) {
  const base = slugify(title) || 'book'
  let id = base
  while (existing.has(id)) {
    id = `${base}-${randomUUID().slice(0, 6)}`
  }
  return id
}

function byNewest(a, b) {
  return (b.addedAt || '').localeCompare(a.addedAt || '')
}

function byFinishedFirst(a, b) {
  return (b.finishedAt || '').localeCompare(a.finishedAt || '') || byNewest(a, b)
}

export async function listBooks() {
  const books = await readAll()
  return {
    reading: books.filter((b) => b.status !== FINISHED).sort(byNewest),
    finished: books.filter((b) => b.status === FINISHED).sort(byFinishedFirst),
  }
}

export async function getBook(id) {
  const books = await readAll()
  return books.find((b) => b.id === id) || null
}

export async function addBook({ title, author, notes }) {
  const cleanTitle = (title || '').trim()
  if (!cleanTitle) throw new ValidationError('Please give the book a title.')

  return withLock(async () => {
    const books = await readAll()
    const book = {
      id: makeId(cleanTitle, new Set(books.map((b) => b.id))),
      title: cleanTitle,
      author: (author || '').trim(),
      notes: (notes || '').trim(),
      status: READING,
      addedAt: new Date().toISOString(),
      finishedAt: null,
    }
    await writeAll([...books, book])
    return book
  })
}

export async function setStatus(id, status) {
  if (status !== READING && status !== FINISHED) {
    throw new ValidationError(`Unknown status: ${status}`)
  }

  return withLock(async () => {
    const books = await readAll()
    const book = books.find((b) => b.id === id)
    if (!book) return null

    book.status = status
    book.finishedAt = status === FINISHED ? new Date().toISOString() : null
    await writeAll(books)
    return book
  })
}

export async function updateNotes(id, notes) {
  return withLock(async () => {
    const books = await readAll()
    const book = books.find((b) => b.id === id)
    if (!book) return null

    book.notes = (notes || '').trim()
    await writeAll(books)
    return book
  })
}

export class ValidationError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ValidationError'
  }
}

