'use server'

import { revalidatePath } from 'next/cache'
import { addBook, FINISHED, READING, setStatus, updateNotes, ValidationError } from '@/lib/books'

export async function addBookAction(_prevState, formData) {
  try {
    const book = await addBook({
      title: formData.get('title'),
      author: formData.get('author'),
      notes: formData.get('notes'),
    })
    revalidatePath('/')
    return { ok: true, addedId: book.id }
  } catch (err) {
    if (err instanceof ValidationError) return { ok: false, error: err.message }
    throw err
  }
}

export async function markFinishedAction(formData) {
  const id = formData.get('id')
  await setStatus(id, FINISHED)
  revalidatePath('/')
  revalidatePath(`/books/${id}`)
}

export async function markReadingAction(formData) {
  const id = formData.get('id')
  await setStatus(id, READING)
  revalidatePath('/')
  revalidatePath(`/books/${id}`)
}

export async function saveNotesAction(_prevState, formData) {
  const id = formData.get('id')
  await updateNotes(id, formData.get('notes'))
  revalidatePath(`/books/${id}`)
  return { ok: true }
}

