import Link from 'next/link'
import AddBookForm from '@/components/AddBookForm'
import { markFinishedAction } from './actions'
import { listBooks } from '@/lib/books'

export const dynamic = 'force-dynamic'

function formatDate(iso) {
  if (!iso) return null
  return new Date(iso).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  })
}

function BookRow({ book, showFinishButton }) {
  return (
    <li className="book-row">
      <div className="book-row-main">
        <Link href={`/books/${book.id}`} className="book-link">
          {book.title}
        </Link>
        <p className="book-meta">
          {book.author || 'Unknown author'}
          {book.finishedAt ? ` · finished ${formatDate(book.finishedAt)}` : ''}
        </p>
      </div>
      {showFinishButton ? (
        <form action={markFinishedAction}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit" className="button-secondary">
            Mark finished
          </button>
        </form>
      ) : null}
    </li>
  )
}

export default async function HomePage() {
  const { reading, finished } = await listBooks()

  return (
    <div className="stack">
      <section>
        <h2>
          Currently reading <span className="count">{reading.length}</span>
        </h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing on the go. Add a book below.</p>
        ) : (
          <ul className="book-list">
            {reading.map((book) => (
              <BookRow key={book.id} book={book} showFinishButton />
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>
          Finished <span className="count">{finished.length}</span>
        </h2>
        {finished.length === 0 ? (
          <p className="empty">No finished books yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((book) => (
              <BookRow key={book.id} book={book} />
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Add a book</h2>
        <AddBookForm />
      </section>
    </div>
  )
}

