'use client'

import { useActionState, useEffect, useRef } from 'react'
import { useFormStatus } from 'react-dom'
import { addBookAction } from '@/app/actions'

function SubmitButton() {
  const { pending } = useFormStatus()
  return (
    <button type="submit" className="button-primary" disabled={pending}>
      {pending ? 'Adding…' : 'Add book'}
    </button>
  )
}

export default function AddBookForm() {
  const [state, formAction] = useActionState(addBookAction, { ok: false })
  const formRef = useRef(null)

  // Clear the fields once a book has actually been saved, so the next one can
  // be typed straight away.
  useEffect(() => {
    if (state.ok) formRef.current?.reset()
  }, [state])

  return (
    <form ref={formRef} action={formAction} className="add-form">
      <label>
        Title
        <input name="title" type="text" autoComplete="off" required />
      </label>
      <label>
        Author
        <input name="author" type="text" autoComplete="off" />
      </label>
      <label>
        Notes <span className="hint">optional</span>
        <textarea name="notes" rows={3} />
      </label>
      {state.error ? (
        <p className="error" role="alert">
          {state.error}
        </p>
      ) : null}
      <SubmitButton />
    </form>
  )
}

