import NotesForm from '@/components/NotesForm'
import { markFinishedAction, markReadingAction } from '@/app/actions'
import { FINISHED, getBook } from '@/lib/books'

export const dynamic = 'force-dynamic'

function formatDate(iso) {
  if (!iso) return null
  return new Date(iso).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  })
}

export async function generateMetadata({ params }) {
  const { id } = await params
  const book = await getBook(id)
  if (!book) return { title: 'Book not found' }
  return {
    title: book.author ? `${book.title} — ${book.author}` : book.title,
  }
}

export default async function BookPage({ params }) {
  const { id } = await params
  const book = await getBook(id)
  if (!book) notFound()

  const isFinished = book.status === FINISHED

  return (
    <article className="stack">
      <div>
        <Link href="/" className="back-link">
          ← Reading list
        </Link>
        <h1 className="book-title">{book.title}</h1>
        <p className="book-author">{book.author || 'Unknown author'}</p>
        <p className="book-meta">
          <span className={isFinished ? 'badge badge-finished' : 'badge'}>
            {isFinished ? 'Finished' : 'Reading'}
          </span>
          {isFinished && book.finishedAt ? ` on ${formatDate(book.finishedAt)}` : null}
          {!isFinished && book.addedAt ? ` since ${formatDate(book.addedAt)}` : null}
        </p>
      </div>

      <form action={isFinished ? markReadingAction : markFinishedAction}>
        <input type="hidden" name="id" value={book.id} />
        <button type="submit" className={isFinished ? 'button-secondary' : 'button-primary'}>
          {isFinished ? 'Move back to reading' : 'Mark as finished'}
        </button>
      </form>

      <section>
        <h2>Notes</h2>
        <NotesForm id={book.id} notes={book.notes} />
      </section>
    </article>
  )
}

