'use client'

import { useActionState } from 'react'
import { useFormStatus } from 'react-dom'
import { saveNotesAction } from '@/app/actions'

function SubmitButton() {
  const { pending } = useFormStatus()
  return (
    <button type="submit" className="button-secondary" disabled={pending}>
      {pending ? 'Saving…' : 'Save notes'}
    </button>
  )
}

export default function NotesForm({ id, notes }) {
  const [state, formAction] = useActionState(saveNotesAction, { ok: false })

  return (
    <form action={formAction} className="notes-form">
      <input type="hidden" name="id" value={id} />
      <textarea
        name="notes"
        rows={8}
        defaultValue={notes}
        placeholder="What stood out? Quotes, thoughts, where you left off…"
      />
      <div className="notes-actions">
        <SubmitButton />
        {state.ok ? <span className="saved">Saved</span> : null}
      </div>
    </form>
  )
}

