args.content:
:root {
  --bg: #fbfaf8;
  --surface: #ffffff;
  --text: #1e1c1a;
  --muted: #6b665f;
  --line: #e4e0d9;
  --accent: #7a4b2a;
  --accent-text: #ffffff;
  --error: #a3261b;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16151a;
    --surface: #1e1d24;
    --text: #f0eee9;
    --muted: #a29c93;
    --line: #322f39;
    --accent: #c98a5c;
    --accent-text: #201a14;
    --error: #f08a7e;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Helvetica, sans-serif;
  line-height: 1.5;
}

.site-header {
  max-width: 44rem;
  margin: 0 auto;
  padding: 2rem 1.25rem 0;
}

.site-title {
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
}

.site-title:hover {
  color: var(--text);
}

main {
  max-width: 44rem;
  margin: 0 auto;
  padding: 1.5rem 1.25rem 4rem;
}

.stack > * + * {
  margin-top: 2.5rem;
}

h1,
h2 {
  line-height: 1.2;
}

h2 {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  margin: 0 0 0.75rem;
  font-size: 1.05rem;
}

.count {
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--muted);
}

.empty {
  margin: 0;
  color: var(--muted);
  font-size: 0.95rem;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--line);
}

.book-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.85rem 0;
  border-bottom: 1px solid var(--line);
}

.book-row-main {
  min-width: 0;
}

.book-link {
  color: var(--text);
  font-weight: 600;
  text-decoration: none;
}

.book-link:hover {
  text-decoration: underline;
  text-decoration-color: var(--accent);
  text-underline-offset: 3px;
}

.book-meta {
  margin: 0.15rem 0 0;
  color: var(--muted);
  font-size: 0.875rem;
}

.book-title {
  margin: 0.75rem 0 0.25rem;
  font-size: 1.75rem;
}

.book-author {
  margin: 0;
  font-size: 1.05rem;
  color: var(--muted);
}

.badge {
  display: inline-block;
  margin-top: 0.6rem;
  padding: 0.1rem 0.5rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--muted);
}

.badge-finished {
  border-color: transparent;
  background: var(--accent);
  color: var(--accent-text);
}

.back-link {
  color: var(--muted);
  font-size: 0.9rem;
  text-decoration: none;
}

.back-link:hover {
  color: var(--text);
}

.add-form,
.notes-form {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 1.25rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 0.75rem;
}

label {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  font-size: 0.85rem;
  font-weight: 600;
}

.hint {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  width: 100%;
  padding: 0.55rem 0.7rem;
  font: inherit;
  font-weight: 400;
  color: var(--text);
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 0.5rem;
  resize: vertical;
}

input:focus-visible,
textarea:focus-visible,
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

button {
  align-self: flex-start;
  padding: 0.5rem 1rem;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: 0.5rem;
  cursor: pointer;
}

button:disabled {
  opacity: 0.6;
  cursor: progress;
}

.button-primary {
  background: var(--accent);
  color: var(--accent-text);
  border: 1px solid transparent;
}

.button-secondary {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--line);
}

.button-secondary:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--accent);
}

.notes-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.saved {
  font-size: 0.85rem;
  color: var(--muted);
}

.error {
  margin: 0;
  color: var(--error);
  font-size: 0.875rem;
}

