import { mkdtemp, readFile, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { addBook, FINISHED, getBook, listBooks, setStatus, updateNotes, ValidationError } from './books.js'

let dir

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), 'books-'))
  process.env.BOOKS_DATA_DIR = dir
})

afterEach(async () => {
  delete process.env.BOOKS_DATA_DIR
  await rm(dir, { recursive: true, force: true })
})

describe('the reading list', () => {
  it('starts empty when no file exists yet', async () => {
    expect(await listBooks()).toEqual({ reading: [], finished: [] })
  })

  it('adds a book as currently reading and persists it to disk', async () => {
    const book = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' })

    expect(book).toMatchObject({
      id: 'dune',
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Spice.',
      status: 'reading',
      finishedAt: null,
    })

    const onDisk = JSON.parse(await readFile(path.join(dir, 'books.json'), 'utf8'))
    expect(onDisk).toHaveLength(1)
    expect(onDisk[0].id).toBe('dune')
  })

  it('requires a title', async () => {
    await expect(addBook({ title: '   ' })).rejects.toThrow(ValidationError)
  })

  it('gives every book a distinct id even with a repeated title', async () => {
    const a = await addBook({ title: 'Dune' })
    const b = await addBook({ title: 'Dune' })
    expect(a.id).not.toBe(b.id)
    expect(b.id).toMatch(/^dune-/)
  })

  it('builds readable ids from awkward titles', async () => {
    const book = await addBook({ title: 'Æther & Ømens: a Café Story!' })
    expect(book.id).toBe('aether-omens-a-cafe-story')
  })

  it('falls back to a usable id when the title has no latin characters', async () => {
    const book = await addBook({ title: '雪国' })
    expect(book.id).toBe('book')
  })

  it('moves a book between reading and finished', async () => {
    const { id } = await addBook({ title: 'Dune' })

    await setStatus(id, FINISHED)
    let list = await listBooks()
    expect(list.reading).toHaveLength(0)
    expect(list.finished).toHaveLength(1)
    expect(list.finished[0].finishedAt).toBeTruthy()

    await setStatus(id, 'reading')
    list = await listBooks()
    expect(list.reading).toHaveLength(1)
    expect(list.finished).toHaveLength(0)
    expect(list.reading[0].finishedAt).toBeNull()
  })

  it('rejects an unknown status', async () => {
    const { id } = await addBook({ title: 'Dune' })
    await expect(setStatus(id, 'abandoned')).rejects.toThrow(ValidationError)
  })

  it('reads a single book back by id, and nothing for an unknown id', async () => {
    const { id } = await addBook({ title: 'Dune', author: 'Frank Herbert' })
