import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

// The actions call revalidatePath, which only exists inside a request; the store
// behind them is the real thing.
vi.mock('next/cache', () => ({ revalidatePath: vi.fn() }))

const { addBookAction, markFinishedAction, markReadingAction, saveNotesAction } = await import('./actions.js')
const { getBook, listBooks } = await import('@/lib/books')

let dir

function formData(entries) {
  const data = new FormData()
  for (const [key, value] of Object.entries(entries)) data.set(key, value)
  return data
}

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), 'actions-'))
  process.env.BOOKS_DATA_DIR = dir
})

afterEach(async () => {
  delete process.env.BOOKS_DATA_DIR
  await rm(dir, { recursive: true, force: true })
})

describe('the form actions', () => {
  it('adds a book from the form and reports the new id', async () => {
    const state = await addBookAction(
      { ok: false },
      formData({ title: 'Piranesi', author: 'Susanna Clarke', notes: 'Statues.' }),
    )

    expect(state).toEqual({ ok: true, addedId: 'piranesi' })
    expect(await getBook('piranesi')).toMatchObject({ author: 'Susanna Clarke', notes: 'Statues.' })
  })

  it('hands a missing title back to the form instead of throwing', async () => {
    const state = await addBookAction({ ok: false }, formData({ title: '', author: 'Nobody' }))

    expect(state).toEqual({ ok: false, error: 'Please give the book a title.' })
    expect((await listBooks()).reading).toHaveLength(0)
  })

  it('marks a book finished and back again', async () => {
    await addBookAction({ ok: false }, formData({ title: 'Dune' }))

    await markFinishedAction(formData({ id: 'dune' }))
    expect((await listBooks()).finished.map((b) => b.title)).toEqual(['Dune'])

    await markReadingAction(formData({ id: 'dune' }))
    expect((await listBooks()).reading.map((b) => b.title)).toEqual(['Dune'])
  })

  it('saves notes typed on the book page', async () => {
    await addBookAction({ ok: false }, formData({ title: 'Dune' }))

    const state = await saveNotesAction({ ok: false }, formData({ id: 'dune', notes: 'Book two next.' }))

    expect(state).toEqual({ ok: true })
    expect((await getBook('dune')).notes).toBe('Book two next.')
  })
})

